BEGIN;
-- Content and real portfolio photos for the film-decoration product. Preserve unpriced/inactive parent and all existing prices.
DO $g$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.offer_products WHERE id='afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf'::uuid AND updated_at='2026-10-09T14:00:40.088187+00:00'::timestamptz FOR UPDATE) THEN RAISE EXCEPTION 'Rekord zmienił się od odczytu; przerwano zapis.'; END IF; END $g$;
UPDATE public.offer_products SET (name,description,offer_short_description,offer_description,public_description,offer_compact_description,offer_benefits,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,offer_page_enabled,sales_packages_enabled,tags,pricing_addons,offer_additional_requirements,updated_at)=(SELECT name,description,offer_short_description,offer_description,public_description,offer_compact_description,offer_benefits,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,offer_page_enabled,sales_packages_enabled,tags,pricing_addons,offer_additional_requirements,now() FROM jsonb_populate_record(NULL::public.offer_products,'{"name": "Filmowa noc — dekoracja tematyczna", "description": "Modułowa dekoracja sali w klimacie premiery i gali filmowej: wejście z czerwonym dywanem, scenografia, plan zdjęciowy, dekoracja stołów, światło oraz opcjonalny ekran LED. Karta oparta na realizacjach MAVINCI: Gala Oskary Sprzedaży 2023, Sylwester 2024 i Odlotowa 40. Zakres oraz ceny wymagają kalkulacji; produkt pozostaje roboczy do jej zakończenia.", "offer_short_description": "Czerwony dywan, filmowe dekoracje i światło — wybierz elementy swojej filmowej nocy.", "offer_description": "Stwórz oprawę imprezy inspirowaną premierą kinową i galą filmową. Czerwony dywan, filmowe tła, rekwizyty, dekoracja stołów i światło tworzą wspólną aranżację. Poniżej poznasz elementy, z których dobierzemy zestaw do Twojej sali. Ekran LED i nowe wydruki mogą rozszerzyć zakres. Zdjęcia przedstawiają nasze realizacje; konkretne ilości i wyposażenie określa oferta.", "public_description": "Filmowa noc — dekoracja tematyczna\n\nAranżacja sali inspirowana premierą kinową i galą filmową. Łączymy czerwony dywan, dekoracyjne motywy taśmy filmowej, tła, figury i światło z oprawą stołów. Zakres budujemy z wybranych elementów, odpowiednio do miejsca, liczby gości i budżetu. Zdjęcia pokazują nasze wcześniejsze realizacje; ostateczny zestaw i ilości określa oferta.\n\nWejście na premierę\nCzerwony dywan oraz kordony tworzą filmowe wejście. Mogą mu towarzyszyć figury i dekoracje przypominające taśmę filmową. Długość dywanu, liczbę słupków i rozmieszczenie dobieramy do wejścia oraz komunikacji w obiekcie.\n\nScenografia i tła filmowe\nWykorzystujemy motywy gwiazd kina, taśmy i szpule filmowe, figury oraz dostępne tła. Rozstawiamy je jako akcenty wejścia, sali i miejsca do zdjęć. Konkretne wzory, ilości, wymiary oraz stan dekoracji potwierdzamy przed realizacją. Nowy motyw lub personalizowany wydruk wymaga przygotowania projektu i osobnej kalkulacji.\n\nMiejsce do zdjęć\nMożna zbudować kameralny plan filmowy z fotelem reżysera, rekwizytami i odpowiednim tłem. Stanowi on dekoracyjną przestrzeń do zdjęć wykonywanych przez gości. Fotograf, fotolustro lub fotobudka są dodatkowymi usługami. Rekwizyty występujące także w dekoracji wejścia liczymy jeden raz, zgodnie z ich faktycznym rozmieszczeniem.\n\nDekoracja stołów\nProponujemy połączenie czerni, czerwieni lub burgundu ze złotymi akcentami. Zakres może obejmować uzgodnione kompozycje, tematyczne dodatki, numerację, serwetki i dekoracyjne podtalerze. Liczba stołów i nakryć oraz podział wyposażenia między hotel a MAVINCI są ustalane przed wyceną. Zdjęcie pokazuje przykład aranżacji, a nie automatycznie pełny zestaw florystyki i zastawy.\n\nŚwiatło\nDekoracyjne światło podkreśla ściany i wybrane elementy scenografii. Dodatkowo można wykorzystać oprawy o wyglądzie retro. Dobór ilości, kolorów oraz ustawienia zależy od wnętrza. Efekty sceniczne, ruchome światło i realizator prowadzący zmiany podczas programu wymagają osobnego zakresu.\n\nEkran LED i personalizacja\nOpcjonalny ekran LED może prezentować nazwę wydarzenia, planszę powitalną i przygotowaną oprawę filmową. Format ekranu, konstrukcję, miejsce ustawienia, zasilanie, treści i sposób obsługi ustalamy dla konkretnej sali. Ekran nie oznacza automatycznie zamówienia sceny, nagłośnienia ani realizacji koncertu. Możliwe są również personalizowane bannery oraz wycinane postacie 2D na PCV, po ustaleniu projektu i wymiarów.\n\nMontaż i logistyka\nTransport, praca ekipy, montaż i demontaż są kalkulowane wspólnie dla wybranego zestawu. Wyceniając kilka elementów nie naliczamy ponownie tej samej pracy i logistyki. Potrzebujemy planu sali, dostępu do zasilania, godzin rozładunku, montażu i odbioru oraz informacji o ograniczeniach obiektu. W niskich salach dobieramy dekoracje wolnostojące z uwzględnieniem podstaw i instalacji sufitowych.\n\nInspiracje z naszych realizacji\nFilmowe wejście, scenografię gali, dekoracje stołów oraz wykorzystanie LED można zobaczyć w realizacji Gala Oskary Sprzedaży 2023. Sylwester 2024 pokazuje motywy taśmy filmowej i aranżację z fotelem reżysera. Odlotowa 40 prezentuje oprawę światłem i retro. Występy artystyczne, kasyno, DJ i pozostałe atrakcje widoczne na zdjęciach nie są automatycznie częścią tego produktu.\n\nZakres i wycena\nWybierz elementy odpowiadające wydarzeniu. W ofercie określimy ilości, wzory, montaż, logistykę i cenę całej aranżacji. Termin, dostępność wyposażenia oraz nowe materiały do produkcji wymagają potwierdzenia.", "offer_compact_description": null, "offer_benefits": ["Elementy dobierane do sali i budżetu", "Spójna oprawa wejścia, stołów i strefy zdjęć", "Inspiracje z rzeczywistych realizacji MAVINCI", "Wspólna kalkulacja montażu i logistyki"], "offer_image_path": "assets/afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf/filmowa-noc-20261012/glowne-wejscie-filmowe.jpg", "offer_image_alt": "Filmowe wejście z czerwonym dywanem, kordonami i dekoracjami — realizacja MAVINCI Gala Oskary Sprzedaży 2023. Zakres zdjęcia jest przykładowy.", "offer_image_position_x": 50, "offer_image_position_y": 50, "offer_image_zoom": 0.9, "offer_page_enabled": true, "sales_packages_enabled": true, "tags": ["dekoracja filmowa", "gala filmowa", "impreza pracownicza", "czerwony dywan"], "pricing_addons": [{"id": "8481e8b8-5962-42a4-8cfc-1b9d3d2f7553", "name": "Personalizowany banner filmowy", "kind": "quantity", "unit": "szt.", "enabled": false, "quantity": 0, "included_quantity": 0, "unit_price": 0, "price_on_request": true, "description": "Nowy projekt i wydruk. Format wyjściowy: szerokość 3 m × wysokość 2 m; konstrukcja, materiał i rzeczywisty format do ustalenia. Nie doliczaj drugi raz, jeśli wydruk ujęto w wybranym zestawie."}, {"id": "5c3e0155-8cf8-4385-93d6-0d70138c565d", "name": "Postać filmowa 2D na PCV", "kind": "quantity", "unit": "szt.", "enabled": false, "quantity": 0, "included_quantity": 0, "unit_price": 0, "price_on_request": true, "description": "Projekt, druk, wycięcie i stabilna podstawa według wybranej postaci oraz wysokości. Wycena po uzgodnieniu wymiarów i materiału."}, {"id": "ae0f097a-50a3-49d5-9c88-e4b10bf9bdb0", "name": "Dodatkowa dekoracja stołu", "kind": "quantity", "unit": "stół", "enabled": false, "quantity": 0, "included_quantity": 0, "unit_price": 0, "price_on_request": true, "description": "Dodatkowy stół ponad liczbę wskazaną w wybranym zestawie. Ten sam uzgodniony zakres aranżacji; nakrycia i wyposażenie hotelu wymagają określenia."}], "offer_additional_requirements": [{"id": "25033ddb-cc97-46d4-9d21-44ed211a49e2", "title": "PLAN SALI I WYSOKOŚĆ", "category": "place", "description": "Rzut lub zdjęcia sali, rzeczywista wysokość, drzwi, instalacje i układ parkietu. Wymiary dekoracji uwzględniają podstawy oraz konstrukcje."}, {"id": "127e71b5-e6c0-4823-a6c2-6b801097d734", "title": "STOŁY I WYPOSAŻENIE HOTELU", "category": "resources", "description": "Liczba, kształt i wymiary stołów oraz liczba nakryć. Uzgadniamy, kto zapewnia obrusy, serwetki, podtalerze, zastawę i kwiaty."}, {"id": "fa11ba34-2f73-4ad0-bb87-79554069c6d0", "title": "WYBÓR SCENOGRAFII", "category": "resources", "description": "Przed realizacją zatwierdzamy konkretne tła, figury, rekwizyty, ich ilości i rozmieszczenie. Zdjęcia portfolio przedstawiają przykłady."}, {"id": "16c21c27-0f3f-4beb-8c94-bdd361bde702", "title": "PERSONALIZACJA I TREŚCI LED", "category": "resources", "description": "Nazwa wydarzenia, teksty i materiały graficzne do przygotowania projektu. Treści oraz zakres obsługi ekranu ustalamy przed realizacją."}, {"id": "4d8eef1f-9109-416c-88a6-8f85c44021ce", "title": "MONTAŻ I DEMONTAŻ", "category": "setup", "description": "Adres, rozładunek, parking, dostęp do sali, zasilanie, godziny montażu i demontażu. Logistyka jest kalkulowana raz dla uzgodnionej aranżacji."}]}'::jsonb)) WHERE id='afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf';
