INSERT INTO public.offer_product_equipment(product_id,product_variant_id,equipment_item_id,quantity,is_optional,notes) SELECT 'afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf','1d9190fb-21a4-44a3-ba44-b0761300577d','c271f2a0-63e3-4c22-bf61-69e591721bd0',2,true,'Opcjonalna para opraw Portman P1 EVO. Konfiguracja, podstawy, zasilanie i dostępność do potwierdzenia; ilość nie oznacza rezerwacji.' WHERE NOT EXISTS(SELECT 1 FROM public.offer_product_equipment WHERE product_id='afaa3e98-a1d1-4fe5-a3a1-601d93a4fbdf' AND product_variant_id='1d9190fb-21a4-44a3-ba44-b0761300577d' AND equipment_item_id='c271f2a0-63e3-4c22-bf61-69e591721bd0');
